 * The two policy kinds a limiter file can declare. Each keeps one
 * independent state per key and exposes the same three-step protocol the
 * simulator drives every policy on a route through: advance to a tick,
 * check whether it allows a request, and record one that was allowed by
 * every policy on the route.
 */

/**
 * A token bucket. Tokens are tracked as a numerator over the constant
 * denominator `per`, so that "`refill` tokens for every `per` ticks" never
 * loses the fractional remainder to rounding.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.full = capacity * per
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { numerator: this.full, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      state.numerator += this.refill * delta
      if (state.numerator > this.full) state.numerator = this.full
      state.lastTick = tick
    }
  }

  allows(key) {
    return this.#state(key).numerator >= this.per
  }

  record(key) {
    this.#state(key).numerator -= this.per
  }
}

/**
 * A sliding window. It remembers the ticks of the requests it recorded for
 * a key so it can count how many still fall within `span` of the current
 * tick.
 */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = []
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const ticks = this.#state(key)
    const threshold = tick - this.span
    let drop = 0
    while (drop < ticks.length && ticks[drop] <= threshold) drop++
    if (drop > 0) ticks.splice(0, drop)
  }

  allows(key) {
    return BigInt(this.#state(key).length) < this.limit
  }

  record(key) {
    // The tick most recently advanced to is not stored separately; the
    // simulator always calls advance(key, tick) before record(key, tick).
    throw new Error('SlidingWindow.record requires a tick; use recordAt')
  }

  recordAt(key, tick) {
    this.#state(key).push(tick)
  }
}
"}

