try {
  outcome = simulate(input)
} catch (error) {
  if (error instanceof LimiterError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(2)
  }
  throw error
}

const lines = []
if (mode === 'replay') {
  for (const event of outcome.results) {
    lines.push(event.allowed ? `${event.tick} ${event.key} allow` : `${event.tick} ${event.key} deny ${event.deniedBy}`)
  }
} else {
  let totalAllowed = 0n
  let totalDenied = 0n
  const keys = [...outcome.totals.keys()].sort()
  for (const key of keys) {
    const tally = outcome.totals.get(key)
    lines.push(`${key} allowed=${tally.allowed} denied=${tally.denied}`)
    totalAllowed += BigInt(tally.allowed)
    totalDenied += BigInt(tally.denied)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
}

process.stdout.write(lines.length === 0 ? '' : lines.join('\n') + '\n')
process.exit(0)
